90	#define CHECK_HANDLE(handle, _expr, _cleanup)                                  \
91	  auto handle = _expr;                                                         \
92	  if (handle == nullptr) {                                                     \
93	    printf("[VXDRV] Error: '%s' returned NULL!\n", #_expr);                    \
94	    _cleanup                                                                   \
