97	// All XRT C++ APIs can throw xrt_core::system_error; propagating across the
98	// extern "C" callbacks_t boundary is UB, so every XRT-touching member wraps
99	// in a try/catch and returns -1 on exception. Errors are logged once so a
100	// missing xclbin or AXI-Lite timeout produces a diagnostic, not a silent
101	// SEGV from libstdc++'s unhandled-exception terminate path.
102	#define XRT_TRY(_label) try {
103	#define XRT_CATCH(_ret) }                                                      \
104	  catch (const std::exception& _e) {                                           \
105	    fprintf(stderr, "[VXDRV] XRT exception: %s\n", _e.what());                 \
106	    return _ret;                                                               \
107	  } catch (...) {                                                              \
108	    fprintf(stderr, "[VXDRV] XRT exception (unknown)\n");                      \
109	    return _ret;                                                               \
