113	static void dump_xrt_error(xrtDeviceHandle xrtDevice, xrtErrorCode err) {
114	  size_t len = 0;
115	  xrtErrorGetString(xrtDevice, err, nullptr, 0, &len);
116	  std::vector<char> buf(len);
117	  xrtErrorGetString(xrtDevice, err, buf.data(), buf.size(), nullptr);
118	  printf("[VXDRV] detail: %s!\n", buf.data());
119	}
