124	class vx_device {
125	public:
126	  vx_device()
127	#ifndef CPP_API
128	    : xrtDevice_(nullptr), xrtKernel_(nullptr)
129	#endif
130	  {}
131	
132	  ~vx_device() {
133	  #ifdef SCOPE
134	    vx_scope_stop(this);
135	  #endif
136	  #ifdef CPP_API
137	    // xrt::device / xrt::ip / xrt::bo are RAII. The xrt::bo dtor can throw
138	    // on some shells (e.g. if the underlying device handle was already
139	    // released); a throw out of a destructor terminates the process, so
140	    // swallow it defensively.
141	    try { host_bos_.clear(); } catch (...) {}
142	  #else
143	    if (xrtKernel_) xrtKernelClose(xrtKernel_);
144	    if (xrtDevice_) xrtDeviceClose(xrtDevice_);
145	  #endif
146	  }
147	
148	  int init() {
149	    int device_index = DEFAULT_DEVICE_INDEX;
150	    const char *device_index_s = getenv("XRT_DEVICE_INDEX");
151	    if (device_index_s != nullptr) {
152	      device_index = atoi(device_index_s);
153	    }
154	
155	    const char *xlbin_path_s = getenv("XRT_XCLBIN_PATH");
156	    if (xlbin_path_s == nullptr) {
157	      xlbin_path_s = DEFAULT_XCLBIN_PATH;
158	    }
159	
160	  #ifdef CPP_API
161	
162	    xrt::device xrtDevice;
163	    xrt::uuid   uuid;
164	    XRT_TRY()
165	      xrtDevice = xrt::device(device_index);
166	      uuid      = xrtDevice.load_xclbin(xlbin_path_s);
167	    XRT_CATCH(-1)
168	    xrt::ip xrtKernel;
169	    XRT_TRY()
170	      xrtKernel = xrt::ip(xrtDevice, uuid, KERNEL_NAME);
171	    XRT_CATCH(-1)
172	
173	  #else
174	
175	    CHECK_HANDLE(xrtDevice, xrtDeviceOpen(device_index), {
176	      return -1;
177	    });
178	
179	  #ifndef XRTSIM
180	    CHECK_ERR(xrtDeviceLoadXclbinFile(xrtDevice, xlbin_path_s), {
181	      dump_xrt_error(xrtDevice, err);
182	      xrtDeviceClose(xrtDevice);
183	      return err;
184	    });
185	
186	    xuid_t uuid;
187	    CHECK_ERR(xrtDeviceGetXclbinUUID(xrtDevice, uuid), {
188	      dump_xrt_error(xrtDevice, err);
189	      xrtDeviceClose(xrtDevice);
190	      return err;
191	    });
192	
193	    CHECK_HANDLE(xrtKernel, xrtPLKernelOpenExclusive(xrtDevice, uuid, KERNEL_NAME), {
194	      xrtDeviceClose(xrtDevice);
195	      return -1;
196	    });
197	  #else
198	    xrtKernelHandle xrtKernel = xrtDevice;
199	  #endif
200	
201	  #endif
202	
203	    xrtDevice_ = xrtDevice;
204	    xrtKernel_ = xrtKernel;
205	
206	    CHECK_ERR(this->write_register(MMIO_CTL_ADDR, CTL_AP_RESET), {
207	      return err;
208	    });
209	
210	  #ifdef SCOPE
211	    {
212	      scope_callback_t callback;
213	      callback.registerWrite = [](vx_device_h hdevice, uint64_t value) -> int {
214	        auto device = (vx_device *)hdevice;
215	        uint32_t value_lo = (uint32_t)(value);
216	        uint32_t value_hi = (uint32_t)(value >> 32);
217	        CHECK_ERR(device->write_register(MMIO_SCP_ADDR, value_lo), {
218	          return err;
219	        });
220	        CHECK_ERR(device->write_register(MMIO_SCP_ADDR + 4, value_hi), {
221	          return err;
222	        });
223	        return 0;
224	      };
225	      callback.registerRead = [](vx_device_h hdevice, uint64_t *value) -> int {
226	        auto device = (vx_device *)hdevice;
227	        uint32_t value_lo, value_hi;
228	        CHECK_ERR(device->read_register(MMIO_SCP_ADDR, &value_lo), {
229	          return err;
230	        });
231	        CHECK_ERR(device->read_register(MMIO_SCP_ADDR + 4, &value_hi), {
232	          return err;
233	        });
234	        *value = (((uint64_t)value_hi) << 32) | value_lo;
235	        return 0;
236	      };
237	      CHECK_ERR(vx_scope_start(&callback, this, -1, -1), {
238	        return err;
239	      });
240	    }
241	  #endif
242	
243	  #ifdef CHIPSCOPE
244	    std::cout << "\nPress ENTER to continue after setting up ILA trigger..." << std::endl;
245	    std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
246	  #endif
247	
248	    return 0;
249	  }
250	
251	  // ----- CP register channel -----
252	  int cp_reg_write(uint32_t off, uint32_t value) {
253	    return this->write_register(CP_BASE + off, value);
254	  }
255	
256	  int cp_reg_read(uint32_t off, uint32_t *value) {
257	    return this->read_register(CP_BASE + off, value);
258	  }
259	
260	  // ----- CP-visible host memory (command ring + DMA staging) -----
261	  // On hardware: a host-only XRT BO addressed by the CP's m_axi_host master.
262	  // Under xrtsim: plain process memory dereferenced in-process.
263	  int host_mem_alloc(uint64_t size, void **host_ptr, uint64_t *cp_addr) {
264	    uint64_t asize = aligned_size(size, CACHE_BLOCK_SIZE);
265	  #ifdef CPP_API
266	    // xrt::bo / map / address all may throw under XRT; host_bos_ is touched
267	    // from worker threads so the std::map insert needs a mutex (the map is
268	    // not thread-safe even on disjoint keys).
269	    XRT_TRY()
270	      xrt::bo bo(xrtDevice_, asize, xrt::bo::flags::host_only, 0);
271	      void *ptr     = bo.map<uint8_t *>();
272	      uint64_t addr = bo.address();
273	      {
274	        std::lock_guard<std::mutex> g(host_bos_mu_);
275	        host_bos_.emplace(addr, host_bo_t{std::move(bo), ptr});
276	      }
277	      *host_ptr = ptr;
278	      *cp_addr  = addr;
279	    XRT_CATCH(-1)
280	  #else
281	    void *ptr = aligned_alloc(CACHE_BLOCK_SIZE, asize);
282	    if (ptr == nullptr)
283	      return -1;
284	    *host_ptr = ptr;
285	    *cp_addr  = reinterpret_cast<uint64_t>(ptr);
286	  #endif
287	    return 0;
288	  }
289	
290	  int host_mem_free(uint64_t cp_addr) {
291	  #ifdef CPP_API
292	    XRT_TRY()
293	      std::lock_guard<std::mutex> g(host_bos_mu_);
294	      auto it = host_bos_.find(cp_addr);
295	      if (it == host_bos_.end())
296	        return -1;
297	      host_bos_.erase(it);   // xrt::bo RAII releases the BO
298	    XRT_CATCH(-1)
299	  #else
300	    free(reinterpret_cast<void *>(cp_addr));
301	  #endif
302	    return 0;
303	  }
304	
305	private:
306	
307	  int write_register(uint32_t addr, uint32_t value) {
308	  #ifdef CPP_API
309	    XRT_TRY()
310	      xrtKernel_.write_register(addr, value);
311	    XRT_CATCH(-1)
312	  #else
313	    CHECK_ERR(xrtKernelWriteRegister(xrtKernel_, addr, value), {
314	      dump_xrt_error(xrtDevice_, err);
315	      return err;
316	    });
317	  #endif
318	    return 0;
319	  }
320	
321	  int read_register(uint32_t addr, uint32_t *value) {
322	  #ifdef CPP_API
323	    XRT_TRY()
324	      *value = xrtKernel_.read_register(addr);
325	    XRT_CATCH(-1)
326	  #else
327	    CHECK_ERR(xrtKernelReadRegister(xrtKernel_, addr, value), {
328	      dump_xrt_error(xrtDevice_, err);
329	      return err;
330	    });
331	  #endif
332	    return 0;
333	  }
334	
335	  xrt_device_t xrtDevice_;
336	  xrt_kernel_t xrtKernel_;
337	
338	#ifdef CPP_API
339	  // Host-only BOs (CP-visible host memory), keyed by kernel-visible address.
340	  struct host_bo_t {
341	    xrt::bo bo;
342	    void   *ptr;
343	  };
344	  std::map<uint64_t, host_bo_t> host_bos_;
345	  // std::map isn't thread-safe even on disjoint keys; queue workers race on
346	  // host_mem_alloc/host_mem_free from arbitrary threads. The mutex covers
347	  // the only sites that touch host_bos_ (alloc/free + ~vx_device clear()).
348	  std::mutex                    host_bos_mu_;
349	#endif
350	};
351	
352	#include <callbacks.inc>
