        case (hb_state)
        HB_IDLE: begin
            if (hb_rd_go)      hb_state <= HB_RD;
            else if (hb_wr_go) hb_state <= HB_WR;
        end
        HB_RD: begin
            if (hb_c0_rsp) begin
                hb_data_r <= cp2af_sRxPort.c0.data;
                hb_state  <= HB_RD_RSP;
            end
        end
        HB_RD_RSP: begin
            if (hb_rsp_ready) hb_state <= HB_IDLE;
        end
        HB_WR: begin
            if (hb_c1_rsp) hb_state <= HB_IDLE;
        end
        default: hb_state <= HB_IDLE;
        endcase
    end

